# packet.LevelChunk{Position: protocol.ChunkPos{2, 3}, Dimension: 1,
#   SubChunkCount: protocol.SubChunkRequestModeLimited, HighestSubChunk: 7,
#   CacheEnabled: true, BlobHashes: []uint64{1, 2}, RawPayload: []byte{0xaa}}
V1001_LIMITED = bytes.fromhex("040602feffffff0f070001020100000000000000020000000000000001aa")

# generated by gophertunnel 0a2ecd563:
# packet.LevelChunk{Position: protocol.ChunkPos{2, 3}, Dimension: 0,
