#   RawPayload: []byte{0xaa}}
V1001_LIMITLESS = bytes.fromhex("040600ffffffff0f0001aa")

# generated by gophertunnel b8bd735:
# &packet.LevelChunk{Position: protocol.ChunkPos{2, 3}, Dimension: 0, SubChunkCount: 5,
#   CacheEnabled: false, RawPayload: []byte{0xaa, 0xbb}}
V2168_FULL = bytes.fromhex("0406000500000002aabb")

# generated by gophertunnel b8bd735:
# &packet.LevelChunk{Position: protocol.ChunkPos{2, 3}, Dimension: 1, SubChunkCount: 0,
#   SubChunkLimit: protocol.Option(int32(7)), CacheEnabled: true, BlobHashes: []uint64{1, 2},
