@pytest.mark.parametrize("version", [v975, v1001, v2168])
def test_level_chunk_is_packet_58(version):
    assert version.packets[58] is version.LevelChunkPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_level_chunk_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_level_chunk_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_level_chunk_is_unchanged_between_v975_and_v1001():
    packet = v975.LevelChunkPacket(
        pos=v975.ChunkPos(x=2, z=3),
        dimension_id=0,
        sub_chunks_count=5,
        cache_enabled=False,
        serialized_chunk=PAYLOAD_AB,
    )
    assert bytes(packet) == V1001_FULL


def test_a_v1001_level_chunk_body_does_not_decode_as_a_v2168_one():
    with pytest.raises(ValueError, match="at byte"):
        v2168.LevelChunkPacket.from_bytes(V1001_FULL)


def test_a_v2168_level_chunk_body_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.LevelChunkPacket.from_bytes(V2168_FULL)


def test_level_chunk_2225_appends_the_client_biome_update_flag():
    packet = v2225.LevelChunkPacket(
        pos=v2225.ChunkPos(x=2, z=3),
        dimension_id=0,
        sub_chunks_count=5,
        cache_enabled=False,
        serialized_chunk=PAYLOAD_AB,
        is_client_biome_update=True,
    )
    wire = bytes(packet)
    assert wire[: len(V2168_FULL)] == V2168_FULL
    assert len(wire) == len(V2168_FULL) + 1


def test_level_chunk_2225_round_trips_the_client_biome_update_flag():
    packet = v2225.LevelChunkPacket(is_client_biome_update=True)
    assert v2225.LevelChunkPacket.from_bytes(bytes(packet)) == packet


def test_a_v2168_level_chunk_body_does_not_decode_as_a_v2225_one():
    with pytest.raises(ValueError, match="at byte"):
        v2225.LevelChunkPacket.from_bytes(V2168_FULL)
